    foo = Foo(10)
    # If the bug exists, 'y' might be treated as having no default
    # because CustomParam(1) == inspect.Parameter.empty is True.
    # If it's treated as no default, it will yield only the value (10, 1).
    # If it's treated as having a default, it will yield ('y', 1, CustomParam(1)).

    # Let's see what it actually produces.
    r = repr(foo)
    print(f"Repr: {r}")
    # Expected if fixed: Foo(10)  <- because y=CustomParam(1) and self.y=CustomParam(1), so it's omitted.
    # If bug: Foo(10, CustomParam(1)) <- because it thinks y has no default.
    assert "CustomParam" not in r

