import inspect
from rich.repr import auto_rich_repr

class BadEq:
    def __eq__(self, other):
        return True

def test_func(a=BadEq()):
    pass

class Container:
    def __init__(self, a):
        self.a = a

c = Container(BadEq())
# We want to see if auto_rich_repr correctly identifies that 'a' has a default
# If it uses ==, it will see BadEq() == Parameter.empty as True and think it has no default.
# If it uses is, it will see BadEq() is Parameter.empty as False and see it as a default.

# To verify, we can check the output of auto_rich_repr
# since it's a generator, we can convert to list
result = list(auto_rich_repr(c))
print(f"Result: {result}")

# If the bug is present: result will be [BadEq()]
# If the bug is fixed: result will be [('a', BadEq(), BadEq())]

if len(result) > 0 and isinstance(result[0], tuple):
    print("FIXED")
elif len(result) > 0:
    print("BUG PRESENT")
else:
    print("UNEXPECTED RESULT")

